-- Create payroll period tables for Supabase.
-- Run this against an existing Supabase database that already has the base schema.

begin;

create table if not exists public."monthly" (
    "ID" integer generated by default as identity,
    "P1" date,
    "P2" date,
    "P3" date,
    "P4" date,
    "P5" date,
    "P6" date,
    "P7" date,
    "P8" date,
    "P9" date,
    "P10" date,
    "P11" date,
    "P12" date,
    constraint "PK_monthly" primary key ("ID")
);

create table if not exists public."semi-monthly" (
    "ID" integer generated by default as identity,
    "P1" date,
    "P2" date,
    "P3" date,
    "P4" date,
    "P5" date,
    "P6" date,
    "P7" date,
    "P8" date,
    "P9" date,
    "P10" date,
    "P11" date,
    "P12" date,
    "P13" date,
    "P14" date,
    "P15" date,
    "P16" date,
    "P17" date,
    "P18" date,
    "P19" date,
    "P20" date,
    "P21" date,
    "P22" date,
    "P23" date,
    "P24" date,
    constraint "PK_semi-monthly" primary key ("ID")
);

create table if not exists public."bi-weekly A" (
    "ID" integer generated by default as identity,
    "P1" date,
    "P2" date,
    "P3" date,
    "P4" date,
    "P5" date,
    "P6" date,
    "P7" date,
    "P8" date,
    "P9" date,
    "P10" date,
    "P11" date,
    "P12" date,
    "P13" date,
    "P14" date,
    "P15" date,
    "P16" date,
    "P17" date,
    "P18" date,
    "P19" date,
    "P20" date,
    "P21" date,
    "P22" date,
    "P23" date,
    "P24" date,
    "P25" date,
    "P26" date,
    "M1" numeric(18,2) not null default 0,
    "M2" numeric(18,2) not null default 0,
    constraint "PK_bi-weekly A" primary key ("ID")
);

create table if not exists public."bi-weekly B" (
    "ID" integer generated by default as identity,
    "P1" date,
    "P2" date,
    "P3" date,
    "P4" date,
    "P5" date,
    "P6" date,
    "P7" date,
    "P8" date,
    "P9" date,
    "P10" date,
    "P11" date,
    "P12" date,
    "P13" date,
    "P14" date,
    "P15" date,
    "P16" date,
    "P17" date,
    "P18" date,
    "P19" date,
    "P20" date,
    "P21" date,
    "P22" date,
    "P23" date,
    "P24" date,
    "P25" date,
    "P26" date,
    "M1" numeric(18,2) not null default 0,
    "M2" numeric(18,2) not null default 0,
    constraint "PK_bi-weekly B" primary key ("ID")
);

commit;
